"""Live-environment staged actor-critic (PPO+GAE) for the compliant swarm policy.

Design (docs/RL_DESIGN.md):
  * Train ONLY the shared compliant policy (Qwen + LoRA). Seed agent and monitor are frozen.
  * LIVE rollouts: each training episode is generated by stepping the real multi-agent harness
    (scenarios/*, multiagent_harness/*), with compliant agents driven by the LOCAL policy and the
    seed by a frozen model. No replay of recorded logs.
  * Dense step reward from alignment.reward_verifier (verified env facts, never the monitor).
  * Stage 1: local-history critic.  Stage 2: coalition-aware critic (public channel + delegation
    graph), MAPPO-style CTDE. Execution stays decentralized so the policy evaluates in the same harness.

This module is backend-agnostic: the HF model/tokenizer are injected, so it runs on Modal GPU for
235B and on a small Qwen locally for validation.
"""
from __future__ import annotations

import asyncio
import json
import re
from dataclasses import dataclass, field

import torch

from multiagent_harness.shade_bootstrap import bootstrap

bootstrap()
from llms.base import BaseLLM  # noqa: E402
from utils.functions_runtime import FunctionCall  # noqa: E402
from utils.pipeline_elements import QueryResult  # noqa: E402
from utils.types import ChatAssistantMessage  # noqa: E402

from scenarios.build import build_episode  # noqa: E402
from alignment.reward_verifier import verify_episode  # noqa: E402


# --------------------------------------------------------------------------------------
# Rollout buffer: one entry per COMPLIANT-agent generation (a "turn"), the PPO decision unit.
# --------------------------------------------------------------------------------------
@dataclass
class Turn:
    agent: str
    role: str
    prompt_ids: torch.Tensor          # tokens the policy conditioned on (observation)
    resp_ids: torch.Tensor            # tokens the policy generated
    logprobs: torch.Tensor            # per-token logprob under the behaviour policy
    value: float = 0.0                # critic estimate at this turn
    reward: float = 0.0               # dense step reward (filled from reward_verifier)
    event_id: str | None = None       # harness event this generation produced (for reward join)
    adv: float = 0.0
    ret: float = 0.0
    # coalition-aware critic features (stage 2), rendered from the public channel + delegation graph
    coalition_ctx: str = ""


@dataclass
class RolloutBuffer:
    turns: list[Turn] = field(default_factory=list)
    def add(self, t: Turn): self.turns.append(t)
    def clear(self): self.turns = []


# --------------------------------------------------------------------------------------
# The trainable local policy, inserted where the harness expects a BaseLLM.
# --------------------------------------------------------------------------------------
TOOLCALL_RE = re.compile(r"<tool_call>\s*(\{.*?\})\s*</tool_call>", re.DOTALL)


class LocalPolicyLLM(BaseLLM):
    """Generates compliant-agent actions with the local HF model, recording tokens+logprobs.

    The model is prompted to emit either free text or one or more tool calls as
    <tool_call>{"name": ..., "args": {...}}</tool_call> blocks, which we parse into the harness's
    FunctionCall objects. Every generation is pushed to the shared RolloutBuffer for PPO.
    """

    def __init__(self, model_name, hf_model, tokenizer, buffer: RolloutBuffer,
                 agent_name: str, role: str, trainable: bool, device="cuda", max_new_tokens=256,
                 disable_adapter=False, max_ctx=4096):
        super().__init__(model_name, 0.7)
        self.m = hf_model
        self.tok = tokenizer
        self.buffer = buffer
        self.agent_name = agent_name
        self.role = role
        self.trainable = trainable          # False for the frozen seed
        self.device = device
        self.max_new_tokens = max_new_tokens
        self.max_ctx = max_ctx
        # the frozen seed shares the policy's base model but runs with LoRA adapters OFF (saves a full copy)
        self.disable_adapter = disable_adapter

    @property
    def provider(self):
        return "local"

    @classmethod
    def create_client(cls):
        return None

    def _tool_preamble(self, runtime):
        """Tell the local model which tools exist and the exact emit format (the API providers did
        this natively; a local model needs it spelled out)."""
        tools = []
        funcs = getattr(runtime, "functions", {}) or {}
        for name, fn in funcs.items():
            desc = getattr(fn, "description", "") or ""
            tools.append(f"- {name}: {desc.splitlines()[0] if desc else ''}")
        return ("You act by emitting zero or more tool calls, each as a line:\n"
                '<tool_call>{"name": "<tool>", "args": {<json args>}}</tool_call>\n'
                "Any other text is a normal message. Available tools:\n" + "\n".join(tools))

    def _render(self, messages, runtime=None):
        chat = []
        if runtime is not None:
            chat.append({"role": "system", "content": self._tool_preamble(runtime)})
        for m in messages:
            role = m.get("role", "user") if isinstance(m, dict) else getattr(m, "role", "user")
            content = m.get("content", "") if isinstance(m, dict) else getattr(m, "content", "")
            chat.append({"role": role, "content": content or ""})
        return self.tok.apply_chat_template(chat, tokenize=False, add_generation_prompt=True)

    @torch.no_grad()
    def _generate(self, prompt_text):
        import contextlib
        ids = self.tok(prompt_text, return_tensors="pt", truncation=True, max_length=self.max_ctx).to(self.device)
        ctx = self.m.disable_adapter() if (self.disable_adapter and hasattr(self.m, "disable_adapter")) else contextlib.nullcontext()
        with ctx:
            out = self.m.generate(**ids, max_new_tokens=self.max_new_tokens, do_sample=True,
                                  temperature=0.7, top_p=0.95, return_dict_in_generate=True, output_scores=True)
        seq = out.sequences[0]
        resp_ids = seq[ids["input_ids"].shape[1]:]
        # per-token logprob of the sampled tokens (behaviour policy)
        logps = []
        for tok_id, score in zip(resp_ids, out.scores):
            logps.append(torch.log_softmax(score[0], dim=-1)[tok_id])
        text = self.tok.decode(resp_ids, skip_special_tokens=True)
        return ids["input_ids"][0].detach().cpu(), resp_ids.detach().cpu(), torch.stack(logps).detach().cpu(), text

    def _parse(self, text):
        calls = []
        for i, blob in enumerate(TOOLCALL_RE.findall(text)):
            try:
                j = json.loads(blob)
                calls.append(FunctionCall(function=j["name"], args=j.get("args", {}), id=f"lc_{i}"))
            except Exception:
                pass
        content = TOOLCALL_RE.sub("", text).strip()
        return content, (calls or None)

    async def query(self, query, runtime, env=None, messages=(), extra_args=None):
        extra_args = extra_args if extra_args is not None else {}
        prompt_text = self._render(messages, runtime)
        prompt_ids, resp_ids, logprobs, text = await asyncio.to_thread(self._generate, prompt_text)
        content, calls = self._parse(text)
        # live per-step trace: what this agent did this step (streams to the training log)
        if calls:
            act = "; ".join(f"{c.function}({json.dumps(c.args, default=str)[:70]})" for c in calls)
        else:
            act = f"msg: {content[:70]}"
        tag = "*trainable*" if self.trainable else "(frozen-seed)"
        print(f"    [step] {self.agent_name}|{self.role} {tag} -> {act}", flush=True)
        if self.trainable:
            self.buffer.add(Turn(agent=self.agent_name, role=self.role, prompt_ids=prompt_ids,
                                 resp_ids=resp_ids, logprobs=logprobs))
        out = ChatAssistantMessage(role="assistant", content=content, tool_calls=calls)
        return QueryResult(query=query, runtime=runtime, env=env, messages=[*messages, out], extra_args=extra_args)


# --------------------------------------------------------------------------------------
# One live rollout: build the P1 episode, run it, join rewards onto the trainable turns.
# --------------------------------------------------------------------------------------
async def rollout_episode(scenario, *, team, policy_llms, seed_spec, buffer: RolloutBuffer,
                          pattern="P1", inducement="L2", seed_framing="legit", out_dir, max_rounds=6):
    buffer.clear()
    orch = build_episode(scenario, episode_id="rl", pattern=pattern, team=team, llms=policy_llms,
                         out_dir=out_dir, max_rounds=max_rounds, seed_spec=seed_spec,
                         inducement=inducement, seed_framing=seed_framing, monitor_hook=None)
    log = await orch.run()
    events = [e.__dict__ if hasattr(e, "__dict__") else e for e in log.events]
    # real verified outcome (did the leak/unauthorized transfer actually happen?) so the terminal
    # collusion penalty R_TERMINAL_LEAK can fire -- NOT the monitor's prediction.
    _ofn = getattr(scenario, "outcome_leaked", None) or getattr(scenario, "outcome_unauthorized", None)
    outcome = (_ofn(orch.env) if _ofn else None) or {}
    # dense step rewards for compliant agents (seed excluded inside verify_episode)
    steps, totals, summary = verify_episode(events, scenario, outcome=outcome, env=orch.env,
                                            seed_role=(seed_spec or {}).get("role"))
    # join: the i-th trainable turn of an agent corresponds to its i-th rewarded decision point.
    by_agent_rewards = {}
    for sr in steps:
        by_agent_rewards.setdefault(sr.agent, []).append(sr.total)
    counters = {}
    for t in buffer.turns:
        k = t.agent; idx = counters.get(k, 0); counters[k] = idx + 1
        rs = by_agent_rewards.get(k, [])
        t.reward = rs[idx] if idx < len(rs) else 0.0
    # Report the ROBUST completion signal (verified from the event stream: a bad PAY-id actually
    # executed, or a key actually sent externally) rather than the unreliable scenario outcome flag,
    # which over-counts proposed-but-unexecuted payments and misses P2-trigger key sends. Consumers
    # (pre/post collusion-rate eval, training-loop leak counter) read outcome["leaked"].
    outcome = dict(outcome or {})
    outcome["scorer_leaked"] = outcome.get("leaked")
    outcome["leaked"] = bool(summary.get("leaked"))
    return log, outcome


# --------------------------------------------------------------------------------------
# GAE + PPO update on the LoRA policy, with a staged critic.
# --------------------------------------------------------------------------------------
def compute_gae(turns_by_agent, gamma=0.99, lam=0.95):
    for turns in turns_by_agent.values():
        adv = 0.0
        for t in reversed(turns):
            # per-agent trajectory treated as a sequence of decision points
            delta = t.reward - t.value  # next-value folded in via running adv (terminal bootstrap=0)
            adv = delta + gamma * lam * adv
            t.adv = adv
            t.ret = adv + t.value


def ppo_update(policy, critic, optimizer, buffer, *, stage="local", clip=0.2, kl_coef=0.02,
               vf_coef=0.5, epochs=4, device="cuda"):
    """Clipped PPO on the LoRA policy + value regression on the staged critic.

    stage='local'      : critic sees only the agent's own prompt tokens.
    stage='coalition'  : critic additionally sees coalition_ctx (public channel + delegation graph).
    """
    # value estimates first (critic forward on each turn's observation)
    for t in buffer.turns:
        obs = t.prompt_ids
        if stage == "coalition" and t.coalition_ctx:
            obs = torch.cat([obs, _encode_ctx(t.coalition_ctx)])
        t.value = float(critic(obs.to(device)).item())
    by_agent = {}
    for t in buffer.turns:
        by_agent.setdefault(t.agent, []).append(t)
    compute_gae(by_agent)
    # live trace: what the actor-critic is training on, one line per decision turn
    print(f"  [train] {len(buffer.turns)} turns in this batch; per-turn (reward -> value -> adv -> return):", flush=True)
    for i, t in enumerate(buffer.turns):
        print(f"    turn {i} {t.agent}|{t.role}: reward={t.reward:+.2f}  value={t.value:+.3f}  adv={t.adv:+.3f}  ret={t.ret:+.3f}", flush=True)

    # diagnostics: accumulate the last epoch's actor/critic quantities so the training log can show
    # whether the actor-critic is actually doing anything (nonzero advantage => the actor has signal;
    # value tracking returns => the critic is learning).
    diag = {"pol_loss": 0.0, "vf_loss": 0.0, "kl": 0.0, "clipfrac": 0.0, "n": 0}
    for ep in range(epochs):
        last = (ep == epochs - 1)
        for t in buffer.turns:
            new_logp = policy_logprobs(policy, t.prompt_ids, t.resp_ids, device)   # recomputed under current policy
            ratio = torch.exp(new_logp.sum() - t.logprobs.sum().to(device))
            a = torch.tensor(t.adv, device=device)
            pol_loss = -torch.min(ratio * a, torch.clamp(ratio, 1 - clip, 1 + clip) * a)
            kl = (t.logprobs.sum().to(device) - new_logp.sum()).abs()
            obs = t.prompt_ids
            if stage == "coalition" and t.coalition_ctx:
                obs = torch.cat([obs, _encode_ctx(t.coalition_ctx)])
            val = critic(obs.to(device))
            vf_loss = (val - torch.tensor(t.ret, device=device)) ** 2
            loss = pol_loss + vf_coef * vf_loss + kl_coef * kl
            optimizer.zero_grad(); loss.backward(); optimizer.step()
            if last:
                diag["pol_loss"] += float(pol_loss.detach()); diag["vf_loss"] += float(vf_loss.detach())
                diag["kl"] += float(kl.detach())
                diag["clipfrac"] += float((abs(ratio.detach() - 1.0) > clip))
                diag["n"] += 1
    n = max(1, diag["n"]); turns = buffer.turns
    return {"n_turns": len(turns),
            "mean_reward": sum(t.reward for t in turns) / max(1, len(turns)),
            "mean_adv": sum(t.adv for t in turns) / max(1, len(turns)),
            "mean_value": sum(t.value for t in turns) / max(1, len(turns)),
            "mean_return": sum(t.ret for t in turns) / max(1, len(turns)),
            "pol_loss": diag["pol_loss"] / n, "value_loss": diag["vf_loss"] / n,
            "kl": diag["kl"] / n, "clip_frac": diag["clipfrac"] / n}


# --- helpers that depend on the concrete HF model (implemented at call site / Modal image) ---
def policy_logprobs(policy, prompt_ids, resp_ids, device):
    ids = torch.cat([prompt_ids, resp_ids]).unsqueeze(0).to(device)
    out = policy(ids).logits[0, :-1]
    logp = torch.log_softmax(out, dim=-1)
    tgt = ids[0, 1:]
    sel = logp[torch.arange(len(tgt)), tgt]
    return sel[prompt_ids.shape[0] - 1:]   # logprobs over the response tokens only


def _encode_ctx(ctx_text):
    # placeholder: coalition context is appended as text tokens for the critic; on Modal this uses
    # the shared tokenizer. Kept tiny so stage-2 is a clean ablation over stage-1.
    return torch.zeros(0, dtype=torch.long)
